function kanbanPrefsKey(source,key){return source+':'+key}
function taskBoardAllGroups(tasks,key){const definition=taskBoardGroupDefinition(kanbanSource,key);const used=new Set(tasks.map(task=>taskBoardGroupValue(task,key)));const values=[...definition.values];for(const value of used)if(value!=='__none__'&&!values.includes(value))values.push(value);if(!values.includes('__none__'))values.push('__none__');return values.length?values:['__none__']}
