function removePlanBoardTask(taskId){for(const owner of [...(state.equipment||[]),...(state.plans||[])])owner.tasks=(owner.tasks||[]).filter(item=>String(item.id)!==String(taskId))}
function syncOptimisticEquipment(){const rows=ADIBAutosave.merge([], 'equipment');for(const owner of [...(state.equipment||[]),...(state.plans||[])]){owner.tasks=(owner.tasks||[]).filter(t=>!ADIBAutosave.isPending(t.id));for(const t of rows){const matches=t.machineId?String(t.machineId)===String(owner.id):String(t.planId)===String(owner.id);if(matches&&!owner.tasks.some(x=>String(x.id)===String(t.id)))owner.tasks.unshift(t)}}}
