function stopDrag(e){const drag=state.drag;if(drag?.mode!=='pan'&&drag?.mode!=='pinch'&&drag){const a=state.equipment.find(x=>x.id===drag.id)||state.plans.find(x=>x.id===drag.id);const before=drag.startValues;let reparented=false;if(a&&drag.kind==='plan'&&drag.dropPlanId&&canNestPlan(a.id,drag.dropPlanId)&&String(a.parentId||'')!==String(drag.dropPlanId)){a.parentId=drag.dropPlanId;reparented=true}const changed=a&&before&&(['x','y','width','height'].some(key=>Math.abs(Number(a[key])-Number(before[key]))>0.25)||String(a.parentId||'')!==String(before.parentId||''));if(changed){lastCanvasUndo={id:a.id,kind:drag.kind,before:{...before},after:{x:Number(a.x)||0,y:Number(a.y)||0,width:Number(a.width)||0,height:Number(a.height)||0,parentId:a.parentId||null}};saveLocalPosition(a)}state.snapGuides={x:null,y:null};state.drag=null;state.last=null;pinchState=null;svg.classList.remove('panning');releaseCanvasPointer(e);if(reparented)renderAll();else renderCanvas();return}state.snapGuides={x:null,y:null};state.drag=null;state.last=null;pinchState=null;svg.classList.remove('panning');releaseCanvasPointer(e)}
