function handleCanvasEscapeUndo(event){if(event.key!=='Escape'||event.defaultPrevented)return;const target=event.target;if(target?.closest?.('input,textarea,select,[contenteditable="true"]'))return;if(document.querySelector('.modal-backdrop.open,.personal-kanban-modal,.personal-eisenhower-modal,.tm-layer,.adib-nav-dock.open,#globalContextMenu:not([hidden]),#notificationPanel:not([hidden])')||!document.getElementById('mobileSearchPanel')?.hidden||!document.getElementById('searchResults')?.hidden)return;if(cancelActiveCanvasEdit()){event.preventDefault();event.stopImmediatePropagation();return}if(undoLastCanvasAction()){event.preventDefault();event.stopImmediatePropagation()}}
