function saveRemotePosition(a,layout){const id=String(a.id),position={...layout};let queue=layoutSaveQueues.get(id);if(queue){queue.latest={item:a,position};return queue.promise}queue={latest:{item:a,position},promise:null};queue.promise=(async()=>{while(queue.latest){const next=queue.latest;queue.latest=null;await writeRemotePosition(next.item,next.position)}})().finally(()=>{if(layoutSaveQueues.get(id)===queue)layoutSaveQueues.delete(id)});layoutSaveQueues.set(id,queue);return queue.promise}
