function preserveActiveBoardScroll(modal,render){const selectors='.kanban-board,.kanban-column-body,.personal-kanban-board,.personal-kanban-column,.eisenhower-quadrant,[data-eisenhower-group]';const key=(node,index)=>{if(node.id)return node.id;const owner=node.closest('[data-kanban-group-column],[data-personal-status-column],[data-eisenhower-group]');for(const name of ['data-kanban-group-column','data-personal-status-column','data-eisenhower-group'])if(owner?.hasAttribute(name))return name+':'+owner.getAttribute(name)+':'+node.className;return node.className+':'+index;};const nodes=()=>[modal,...modal.querySelectorAll(selectors)];const old=nodes().map((node,index)=>({node,key:key(node,index),x:node.scrollLeft,y:node.scrollTop}));const active=document.activeElement,id=modal.contains(active)?active.id:'',selection=id&&active.selectionStart!=null?[active.selectionStart,active.selectionEnd]:null;render();const current=new Map(nodes().map((node,index)=>[key(node,index),node]));for(const item of old){const node=item.node.isConnected?item.node:current.get(item.key);if(node){node.scrollLeft=item.x;node.scrollTop=item.y;}}if(id){const field=document.getElementById(id);field?.focus({preventScroll:true});if(selection&&field?.setSelectionRange)field.setSelectionRange(...selection);}}
